package com.hbm.machine.pa.cooled;
import api.hbm.redstoneoverradio.IRORInteractive;
import com.hbm.api.computer.*;
import com.hbm.machine.pa.physics.*;
import com.hbm.multiblock.DummyableBlock;
import com.hbm.world.structure.generated.compat.ForgeDirection;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
/** The original non-entity, source-owned particle simulation; never forces chunks into existence. */
public final class PaSourceEntity extends PaCooledEntity implements PaParticle.Source,IRORInteractive ,com.hbm.multiblock.proxy.SourceProxyInventoryAccess {
 public static final long USAGE=100000;public PaParticle particle;public PaState state=PaState.IDLE;public int lastSpeed,debugSpeed;
 public PaSourceEntity(BlockPos pos,BlockState block){super(PaContent.ENTITY.get(),PaKind.SOURCE,pos,block);}
 @Override public void updateState(PaState state){this.state=state;}@Override public void lastSpeed(int momentum){lastSpeed=momentum;}
 @Override protected void beforeCooling(ServerLevel level){int steps=particle==null?1:1+Math.clamp(particle.momentum/1000,0,9);for(int i=0;i<steps;i++){if(particle!=null){state=PaState.RUNNING;steppy(level);debugSpeed=particle.momentum;if(particle.invalid)particle=null;}else if(hasPower(USAGE)&&!slots[1].isEmpty()&&!slots[2].isEmpty()){tryRun();break;}}}
 private void steppy(ServerLevel level){BlockPos pos=new BlockPos(particle.x,particle.y,particle.z);if(!level.hasChunkAt(pos)){state=PaState.PAUSE_UNLOADED;return;}if(!(level.getBlockState(pos).getBlock() instanceof DummyableBlock block)){particle.crash(PaState.CRASH_DERAIL);return;}BlockPos core=block.findCore(level,pos,unavailable->state=PaState.PAUSE_UNLOADED);if(core==null&&state==PaState.PAUSE_UNLOADED)return;if(core==null||!(level.getBlockEntity(core) instanceof PaParticleUser machine)){particle.crash(PaState.CRASH_DERAIL);return;}if(!machine.canParticleEnter(particle,particle.dir,particle.x,particle.y,particle.z)){particle.crash(PaState.CRASH_CANNOT_ENTER);return;}machine.onEnter(particle,particle.dir);var exit=machine.getExitPos(particle);if(exit!=null)particle.move(exit);}
 private void tryRun(){if(!isCool())return;var first=slots[1].getCraftingRemainingItem();var second=slots[2].getCraftingRemainingItem();if(!first.isEmpty()&&!slots[3].isEmpty()||!second.isEmpty()&&!slots[4].isEmpty())return;if(!first.isEmpty())slots[3]=first.copy();if(!second.isEmpty())slots[4]=second.copy();usePower(USAGE);var axis=ForgeDirection.getOrientation(DummyableBlock.facing(getBlockState()).get3DDataValue()).getRotation(ForgeDirection.DOWN);particle=new PaParticle(this,worldPosition.getX()+axis.offsetX*5,worldPosition.getY(),worldPosition.getZ()+axis.offsetZ*5,axis,slots[1],slots[2]);slots[1]=ItemStack.EMPTY;slots[2]=ItemStack.EMPTY;setChanged();}
 public void cancel(){particle=null;state=PaState.IDLE;setChanged();}@Override public void control(CompoundTag tag){if(tag.contains("cancel"))cancel();}
 @Override protected void writeState(CompoundTag tag,HolderLookup.Provider lookup){if(particle==null)return;var p=new CompoundTag();p.putInt("x",particle.x);p.putInt("y",particle.y);p.putInt("z",particle.z);p.putByte("dir",(byte)particle.dir.ordinal());p.putInt("momentum",particle.momentum);p.putInt("defocus",particle.defocus);p.putInt("dist",particle.distanceTraveled);p.put("input1",particle.input1.save(lookup));p.put("input2",particle.input2.save(lookup));tag.put("particle",p);}
 @Override protected void readState(CompoundTag tag,HolderLookup.Provider lookup){particle=null;if(!tag.contains("particle"))return;var p=tag.getCompound("particle");particle=new PaParticle(this,p.getInt("x"),p.getInt("y"),p.getInt("z"),ForgeDirection.getOrientation(p.getInt("dir")),ItemStack.parseOptional(lookup,p.getCompound("input1")),ItemStack.parseOptional(lookup,p.getCompound("input2")));particle.momentum=p.getInt("momentum");particle.defocus=p.getInt("defocus");particle.distanceTraveled=p.getInt("dist");}
 @Override protected void writeSnapshot(CompoundTag tag){tag.putInt("debugSpeed",debugSpeed);tag.putInt("state",state.ordinal());tag.putInt("lastSpeed",lastSpeed);}@Override protected void readSnapshot(CompoundTag tag){debugSpeed=tag.getInt("debugSpeed");state=PaState.values()[Math.clamp(tag.getInt("state"),0,PaState.values().length-1)];lastSpeed=tag.getInt("lastSpeed");}
 @Override public int[] accessibleAt(BlockPos port,Direction side){Direction dir=DummyableBlock.facing(getBlockState()),rot=dir.getClockWise();if(port.equals(worldPosition.relative(dir).relative(rot,-2))||port.equals(worldPosition.relative(dir,-1).relative(rot,2)))return new int[]{2,3,4};if(port.equals(worldPosition.relative(dir,-1).relative(rot,-2))||port.equals(worldPosition.relative(dir).relative(rot,2)))return new int[]{1,3,4};return super.accessibleAt(port,side);}
 @Override public String[] computerMethods(){return new String[]{"getEnergyInfo","getCoolant","getMomentum","getState","getCrafting","cancelOperation","getInfo"};}
 @Override public Object[] callComputer(String name,ComputerArguments args){return switch(name){case "getMomentum"->new Object[]{lastSpeed};case "getState"->new Object[]{state.name()};case "getCrafting"->craftingInfo();case "cancelOperation"->{cancel();yield new Object[0];}case "getInfo"->{var values=new ArrayList<>(Arrays.asList(basicInfo()));values.addAll(Arrays.asList(craftingInfo()));values.add(lastSpeed);values.add(state.name());yield values.toArray();}default->super.callComputer(name,args);};}
 @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"status",PREFIX_VALUE+"momentum",PREFIX_VALUE+"defocus",PREFIX_VALUE+"temperature",PREFIX_VALUE+"pfmcold",PREFIX_VALUE+"pfm",PREFIX_FUNCTION+"cancel"};}@Override public String provideRORValue(String name){return switch(name){case PREFIX_VALUE+"status"->state.name();case PREFIX_VALUE+"momentum"->Integer.toString(lastSpeed);case PREFIX_VALUE+"defocus"->Integer.toString(particle==null?0:particle.defocus);default->super.provideRORValue(name);};}@Override public String runRORFunction(String name,String[] params){if(name.equals(PREFIX_FUNCTION+"cancel"))cancel();return null;}

 @Override public int[] sourceProxySlots(net.minecraft.core.BlockPos position,net.minecraft.core.Direction side){return accessibleAt(position,side);}
}
